const body = $input.first().json.body;

if (!body || !body.lease_text) {
  throw new Error('Missing lease_text in request body. Send a POST request with { "lease_text": "..." }');
}

const leaseText = body.lease_text.trim();

if (leaseText.length < 100) {
  throw new Error('lease_text is too short. Please provide a full or partial lease document.');
}

return [{
  json: {
    lease_text: leaseText,
    char_count: leaseText.length,
    received_at: new Date().toISOString()
  }
}];

// Parse extraction output
let extractedFields = {};
try {
  const rawExtraction = $('Extract Lease Fields').first().json.message.content;
  const cleaned = rawExtraction.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  extractedFields = JSON.parse(cleaned);
} catch(e) {
  extractedFields = { parse_error: 'Could not parse extraction output', raw: $('Extract Lease Fields').first().json.message.content };
}

// Parse flagging output
let flaggedClauses = [];
try {
  const rawFlags = $('Flag Unusual Clauses').first().json.message.content;
  const cleaned = rawFlags.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  const parsed = JSON.parse(cleaned);
  flaggedClauses = parsed.flagged_clauses || [];
} catch(e) {
  flaggedClauses = [{ parse_error: 'Could not parse flagging output' }];
}

// Count risk levels
const highRisk = flaggedClauses.filter(c => c.risk_level === 'high').length;
const mediumRisk = flaggedClauses.filter(c => c.risk_level === 'medium').length;
const lowRisk = flaggedClauses.filter(c => c.risk_level === 'low').length;

// Build final output
const output = {
  meta: {
    processed_at: new Date().toISOString(),
    model: 'gpt-4o',
    workflow_version: '1.0.0',
    disclaimer: 'AI-generated draft. Every field must be reviewed and verified by a qualified lawyer before use in any legal or financial decision.'
  },
  summary: {
    total_flagged_clauses: flaggedClauses.length,
    high_risk_clauses: highRisk,
    medium_risk_clauses: mediumRisk,
    low_risk_clauses: lowRisk,
    review_recommendation: highRisk > 0 ? 'PRIORITY REVIEW REQUIRED — high risk clauses identified' : mediumRisk > 0 ? 'REVIEW RECOMMENDED — medium risk clauses identified' : 'STANDARD REVIEW — no high-risk clauses identified'
  },
  extracted_fields: extractedFields,
  flagged_clauses: flaggedClauses
};

return [{ json: output }];
